"""Restore packaged sources without changing datasets, results, or notebooks."""
from pathlib import Path
import json,base64,zlib,time
PAYLOAD = ''
root=Path(__file__).resolve().parent
sources=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
for name,encoded in sources.items():
    path=root/name;content=base64.b64decode(encoded)
    if path.exists() and path.read_bytes()!=content:
        path.rename(path.with_name(path.name+'.backup-'+str(time.time_ns())))
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_bytes(content)
    assert path.read_bytes()==content
print(f'Restored and verified {len(sources)} files in {root}. Data, outputs, and notebooks preserved.')
